begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,email_confirmed_at,raw_user_meta_data) values
('99000000-0000-4000-8000-000000000001','guest-host@example.test',now(),'{"display_name":"Host"}'),
('99000000-0000-4000-8000-000000000002','guest-account@example.test',now(),'{"display_name":"Account"}');
insert into private.community_onboarding_state(user_id,status,current_step,started_at,completed_at) values ('99000000-0000-4000-8000-000000000001','completed','completed',now(),now());
insert into public.events(id,organizer_id,title,description,start_time,end_time,location_type,status,capacity,registration_scope,requires_approval) values
('99100000-0000-4000-8000-000000000001','99000000-0000-4000-8000-000000000001','Guest event','Public guest event',now()+interval '1 hour',now()+interval '3 hours','virtual','approved',1,'public',false),
('99100000-0000-4000-8000-000000000002','99000000-0000-4000-8000-000000000001','Approval event','Public approval event',now()+interval '1 hour',now()+interval '3 hours','virtual','approved',null,'public',true),
('99100000-0000-4000-8000-000000000003','99000000-0000-4000-8000-000000000001','Community event','Members only registration',now()+interval '1 hour',now()+interval '3 hours','virtual','approved',null,'community',false);
insert into private.event_access_details(event_id,join_url) select id,'https://example.test/PRIVATE-SECRET' from public.events where organizer_id='99000000-0000-4000-8000-000000000001';
select ok(not has_function_privilege('anon','public.request_event_guest_link(uuid,text,text,text)','EXECUTE'),'Browsers cannot bypass Turnstile and send guest emails through an RPC');
select ok(not has_function_privilege('authenticated','public.event_guest_receipt(uuid,text,text)','EXECUTE'),'Authenticated browsers cannot bypass the service credential boundary');
select ok(not has_table_privilege('anon','private.event_guest_links','SELECT'),'Guest email and token hashes are private');
select ok(not has_table_privilege('authenticated','private.event_guest_links','SELECT'),'Members cannot enumerate guest identities or credentials');
set local role service_role;
select is(public.request_event_guest_link('99100000-0000-4000-8000-000000000003','guest@example.test','Guest',repeat('a',64)),false,'Guest requests cannot bypass community-only registration');
select is(public.request_event_guest_link('99100000-0000-4000-8000-000000000001','guest@example.test','Guest',repeat('a',64)),true,'Public events accept a name/email guest request');
select is(public.event_guest_receipt('99100000-0000-4000-8000-000000000001',repeat('a',64),'receipt')->>'needsConfirmation','true','Opening a link never allocates a seat');
select is(public.event_guest_receipt('99100000-0000-4000-8000-000000000001',repeat('a',64),'receipt')->>'joinUrl',null,'Unconfirmed email receives no private access');
select throws_ok($$select public.event_guest_receipt('99100000-0000-4000-8000-000000000002',repeat('a',64),'confirm')$$,'42501',null,'A link cannot authorize another event');
select is(public.event_guest_receipt('99100000-0000-4000-8000-000000000001',repeat('a',64),'confirm')->>'status','confirmed','Explicit email proof reserves the first place without platform membership');
select is(public.event_guest_receipt('99100000-0000-4000-8000-000000000001',repeat('a',64),'confirm')->>'status','confirmed','Confirmation replay is idempotent');
select is(public.event_guest_receipt('99100000-0000-4000-8000-000000000001',repeat('a',64),'receipt')->>'joinUrl','https://example.test/PRIVATE-SECRET','Only confirmed guests receive the private URL');
select is(public.request_event_guest_link('99100000-0000-4000-8000-000000000001','waitlist@example.test','Waiting guest',repeat('b',64)),true,'Another email can request a link');
select is(public.event_guest_receipt('99100000-0000-4000-8000-000000000001',repeat('b',64),'confirm')->>'status','waitlisted','Guests share the same capacity limit');
select is(public.event_guest_receipt('99100000-0000-4000-8000-000000000001',repeat('b',64),'receipt')->>'joinUrl',null,'A guest waitlist receipt excludes access credentials');
select is(public.event_guest_receipt('99100000-0000-4000-8000-000000000001',repeat('a',64),'cancel')->>'status','cancelled','A private link can cancel only its registration');
select is(public.event_guest_receipt('99100000-0000-4000-8000-000000000001',repeat('b',64),'receipt')->>'status','confirmed','Cancellation atomically promotes a verified guest');
select is(public.request_event_guest_link('99100000-0000-4000-8000-000000000002','approval@example.test','Review guest',repeat('c',64)),true,'Approval event accepts guest proof');
select is(public.event_guest_receipt('99100000-0000-4000-8000-000000000002',repeat('c',64),'confirm')->>'status','pending','Email verification does not bypass host approval');
select is(public.event_guest_receipt('99100000-0000-4000-8000-000000000002',repeat('c',64),'receipt')->>'joinUrl',null,'Pending guest receives no private access');
select is(public.request_event_guest_link('99100000-0000-4000-8000-000000000001','guest@example.test','Guest',repeat('d',64)),true,'Email owner can request another private link');
select is(public.request_event_guest_link('99100000-0000-4000-8000-000000000001','guest@example.test','Guest',repeat('e',64)),true,'Email request budget allows three attempts');
select is(public.request_event_guest_link('99100000-0000-4000-8000-000000000001','guest@example.test','Guest',repeat('f',64)),false,'Email rate limit closes the fourth request');
reset role;
select is((select count(*)::int from private.event_registrations where event_id='99100000-0000-4000-8000-000000000001'),2,'Two identities have exactly two registrations');
select is((select count(*)::int from auth.users where email='guest@example.test'),0,'Guest registration does not create a platform account');
update private.event_guest_links set expires_at=now()-interval '1 second' where token_hash=repeat('d',64);
set local role service_role;
select throws_ok($$select public.event_guest_receipt('99100000-0000-4000-8000-000000000001',repeat('d',64),'confirm')$$,'42501',null,'Expired verification links fail closed');
reset role;
set local role authenticated;
set local "request.jwt.claim.sub"='99000000-0000-4000-8000-000000000001';
select is((select count(*)::int from public.get_event_guest_list('99100000-0000-4000-8000-000000000001') where display_name='Waiting guest'),1,'Host sees the guest name without a public email list');
select lives_ok($$select public.manage_event_guest('99100000-0000-4000-8000-000000000002',(select id from public.get_event_guest_list('99100000-0000-4000-8000-000000000002')),'approve','99000000-0000-4000-8000-000000000001')$$,'Hosts can approve verified public guests');
select lives_ok($$select public.manage_event_guest('99100000-0000-4000-8000-000000000001',(select id from public.get_event_guest_list('99100000-0000-4000-8000-000000000001') where status='confirmed'),'check_in','99000000-0000-4000-8000-000000000001')$$,'Hosts can check in a confirmed email guest');
reset role;
set local role service_role;
select throws_ok($$select public.event_guest_receipt('99100000-0000-4000-8000-000000000001',repeat('b',64),'cancel')$$,'22023',null,'Guest cannot erase checked-in attendance');
reset role;
set local role authenticated;
set local "request.jwt.claim.sub"='99000000-0000-4000-8000-000000000002';
select is(public.register_for_event('99100000-0000-4000-8000-000000000002','99000000-0000-4000-8000-000000000002')->>'status','pending','A verified account without Community membership can register for a public event');
reset role;
set local role service_role;
select is(public.request_event_guest_link('99100000-0000-4000-8000-000000000002','guest-account@example.test','Same account',repeat('1',64)),true,'A known email can request its private receipt');
select is(public.event_guest_receipt('99100000-0000-4000-8000-000000000002',repeat('1',64),'confirm')->>'status','pending','Email guest path reuses an existing authenticated registration');
reset role;
select is((select count(*)::int from private.event_registrations where event_id='99100000-0000-4000-8000-000000000002' and user_id='99000000-0000-4000-8000-000000000002'),1,'Account and email proof never double book');
set local role anon;
select is((select count(*)::int from public.discover_host_events('99000000-0000-4000-8000-000000000001')),3,'Anonymous profile activity uses only the safe public event projection');
select ok((select bool_and(location is null) from public.discover_host_events('99000000-0000-4000-8000-000000000001')),'Public profile projection cannot expose a private venue');
select throws_ok($$select * from public.discover_host_events('99000000-0000-4000-8000-000000000001',1000)$$,'22023',null,'Public host event limits are bounded');
reset role;
select * from finish();
rollback;
